package com.vaultora.vault;
import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.annotation.Version;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;
@Document("vaults") public class Vault { @Id private String id; @Indexed(unique=true) private String userId; private String ciphertext;private String iv;private String salt;private int version;private Instant createdAt;private Instant updatedAt;@Version private Long revision;
 public String getId(){return id;}public String getUserId(){return userId;}public String getCiphertext(){return ciphertext;}public String getIv(){return iv;}public String getSalt(){return salt;}public int getVersion(){return version;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Long getRevision(){return revision==null?0:revision;}public void setUserId(String v){userId=v;}public void setCiphertext(String v){ciphertext=v;}public void setIv(String v){iv=v;}public void setSalt(String v){salt=v;}public void setVersion(int v){version=v;}public void setCreatedAt(Instant v){createdAt=v;}public void setUpdatedAt(Instant v){updatedAt=v;}
}
